{
  "hasCompletedOnboarding": true
  {{- if .secrets.ANTHROPIC_API_KEY }},
  "primaryApiKey": {{ .secrets.ANTHROPIC_API_KEY | json }}
  {{- end }}
  {{- range .sources }}{{- if eq .slug "primary" }},
  "projects": {
    {{ .target | json }}: {
      "hasTrustDialogAccepted": true
    }
  }
  {{- end }}{{- end }}
}

{
  "hasCompletedOnboarding": true
  {{- if .secrets.ANTHROPIC_API_KEY }},
  "primaryApiKey": {{ .secrets.ANTHROPIC_API_KEY | json }}
  {{- end }},
  "projects": {
    {{ .workingDir | json }}: {
      "hasTrustDialogAccepted": true
    }
  }
}

{
  "hasCompletedOnboarding": true,
  "hasSeenAutoDefaultNudge": true
  {{- if .secrets.ANTHROPIC_API_KEY }},
  "primaryApiKey": {{ .secrets.ANTHROPIC_API_KEY | json }}
  {{- end }},
  "projects": {
    {{ .workingDir | json }}: {
      "hasTrustDialogAccepted": true
    }
  }
}

# Managed by Discobox. Policy defaults (approval, sandbox) are the image's
# system layer, /etc/codex/config.toml, which this file may override.
{{- if .workingDir }}

[projects.{{ .workingDir | json }}]
trust_level = "trusted"
{{- end }}

# Managed by Discobox. Policy defaults (approval, sandbox) are the image's
# system layer, /etc/codex/config.toml, which this file may override.
{{- range .sources }}{{- if eq .slug "primary" }}
[projects.{{ .target | json }}]
trust_level = "trusted"
{{- end }}{{- end }}
